package io.github.alighaziam.eom.shipping.infrastructure;
import io.github.alighaziam.eom.shipping.*; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="shipments",schema="shipping") public class ShipmentEntity {
 @Id private UUID id; @Column(name="order_id",nullable=false,unique=true) private UUID orderId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private ShipmentStatus status;
 @Column(name="recipient_name",nullable=false,length=180) private String recipientName; @Column(name="address_line1",nullable=false,length=240) private String addressLine1; @Column(name="address_line2",length=240) private String addressLine2; @Column(nullable=false,length=120) private String city; @Column(name="postal_code",length=40) private String postalCode; @Column(name="country_code",nullable=false,length=2) private String countryCode; @Column(length=40) private String phone; @Column(name="carrier_reference",length=120) private String carrierReference; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected ShipmentEntity(){} public ShipmentEntity(UUID id,UUID orderId,DeliveryAddress a,Instant now){this.id=id;this.orderId=orderId;status=ShipmentStatus.PENDING;recipientName=a.recipientName();addressLine1=a.addressLine1();addressLine2=a.addressLine2();city=a.city();postalCode=a.postalCode();countryCode=a.countryCode();phone=a.phone();createdAt=now;updatedAt=now;carrierReference="sandbox-shipment-"+id;}
 public Shipment toDomain(){return new Shipment(id,orderId,status,new DeliveryAddress(recipientName,addressLine1,addressLine2,city,postalCode,countryCode,phone),carrierReference,createdAt,updatedAt);} public void status(ShipmentStatus s,Instant now){status=s;updatedAt=now;}
}